import csv
import re
from datetime import date, timedelta
from pathlib import Path

LOG_DIR = Path("/app/logs")
TODAY = date(2025, 8, 12)
LAST_7_START = TODAY - timedelta(days=6)
LAST_30_START = TODAY - timedelta(days=29)
MONTH_START = TODAY.replace(day=1)

SEVERITIES = ["ERROR", "WARNING", "INFO"]
FILENAME_RE = re.compile(r"^(\d{4}-\d{2}-\d{2})_.*\.log$")

periods = {
    "today": {s: 0 for s in SEVERITIES},
    "last_7_days": {s: 0 for s in SEVERITIES},
    "last_30_days": {s: 0 for s in SEVERITIES},
    "month_to_date": {s: 0 for s in SEVERITIES},
    "total": {s: 0 for s in SEVERITIES},
}

for log_file in LOG_DIR.glob("*.log"):
    m = FILENAME_RE.match(log_file.name)
    if not m:
        continue
    file_date = date.fromisoformat(m.group(1))

    counts = {s: 0 for s in SEVERITIES}
    with open(log_file, "r", errors="replace") as f:
        for line in f:
            for s in SEVERITIES:
                if f"[{s}]" in line:
                    counts[s] += 1
                    break

    for s in SEVERITIES:
        c = counts[s]
        periods["total"][s] += c
        if file_date == TODAY:
            periods["today"][s] += c
        if LAST_7_START <= file_date <= TODAY:
            periods["last_7_days"][s] += c
        if LAST_30_START <= file_date <= TODAY:
            periods["last_30_days"][s] += c
        if MONTH_START <= file_date <= TODAY:
            periods["month_to_date"][s] += c

with open("/app/summary.csv", "w", newline="") as f:
    writer = csv.writer(f)
    writer.writerow(["period", "severity", "count"])
    for period in ["today", "last_7_days", "last_30_days", "month_to_date", "total"]:
        for s in SEVERITIES:
            writer.writerow([period, s, periods[period][s]])

print("done")

